import React, { useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import BookForm from '../../features/books/BookForm';
import BookList from '../../features/books/BookList';

export default function BooksManagement() {
  const location = useLocation();

  // Wrap BookList so we can trigger refetch from BookForm success
  const BookListWithRefetch = React.useCallback(
    ({ setRefetch }) => (
      <BookList setRefetch={setRefetch} />
    ),
    []
  );

  return (
    <div className="books-management">
      <h1>Books Management</h1>
      <BookForm onBookCreated={(count = 1) => {
        // Toast handled in wrapper; refetch handled via location state in BookList
      }} />
      <BookListWrapper locationState={location.state} />
    </div>
  );
}

function BookListWrapper({ locationState }) {
  const location = useLocation();
  const { books, loading, error, refetch } = useBooks();

  useEffect(() => {
    if (location.state?.booksCreated) {
      refetch();
      window.history.replaceState({}, document.title);
    }
  }, [location.state, refetch]);

  if (loading) return <div className="loading">Loading books...</div>;
  if (error) return <div className="error">Error: {error}</div>;

  return (
    <div className="book-list">
      <h2>All Books</h2>
      <div className="book-grid">
        {books.map((book) => <BookCard key={book.id} book={book} onDeleted={refetch} />)}
      </div>
    </div>
  );
}
